var START_SOC   = 17;
var STOP_SOC    = 19;
var CAPACITY    = 568;
var RESERVE     = 20;
var LOAD_LATE   = 25;
var LOAD_EARLY  = 35;
var CUTOVER_HR  = 21;
var MORNING_HR  = 7;
var BUFFER_SIZE = 6;

var raw = msg.payload;
var socs = [];
var kwhNow = null;
var loadW = null;

if (typeof raw === 'string') {
    var parts = raw.split(',').map(function(v) { return parseFloat(v.trim()); });
    if (parts.length >= 6) { socs = parts.slice(0,4); kwhNow = parts[4]; loadW = parts[5]; }
    else if (parts.length >= 5) { socs = parts.slice(0,4); kwhNow = parts[4]; }
    else { socs = parts; }
} else if (Array.isArray(raw)) {
    for (var i = 0; i < raw.length; i++) {
        var id = raw[i].nodeid || '';
        var val = parseFloat(raw[i].value !== undefined ? raw[i].value : raw[i].payload);
        if (id === 'm12_kwh_total') kwhNow = val;
        else if (id === 'm13_ptot') loadW = val;
        else socs.push(val);
    }
}

socs = socs.filter(function(n) { return !isNaN(n) && n > 0 && n <= 100; });

// Mock data fallback for bench testing (sensors not connected)
if (socs.length === 0) {
    var ms = flow.get('mock_soc');
    if (ms !== null && ms !== undefined) { var msv = parseFloat(ms); if (!isNaN(msv)) socs = [msv,msv,msv,msv]; }
}
if (kwhNow === null || isNaN(kwhNow)) {
    var mk = flow.get('mock_kwh');
    if (mk !== null && mk !== undefined) kwhNow = parseFloat(mk);
}
if (loadW === null || isNaN(loadW)) {
    var ml = flow.get('mock_load');
    if (ml !== null && ml !== undefined) loadW = parseFloat(ml);
}

if (socs.length === 0) { node.status({fill:'grey', text:'no SOC'}); return [null, null]; }

var avg = socs.reduce(function(a,b){return a+b;},0) / socs.length;
flow.set('last_avg_soc', avg);
if (kwhNow !== null && !isNaN(kwhNow)) flow.set('last_kwh', kwhNow);

if (loadW !== null && !isNaN(loadW) && loadW > 0) {
    var buf = flow.get('load_buffer') || [];
    buf.push(loadW);
    if (buf.length > BUFFER_SIZE * 6) buf = buf.slice(-BUFFER_SIZE * 6);
    flow.set('load_buffer', buf);
}

var gen         = flow.get('gen_state')        || 0;
var eveningMode = flow.get('evening_mode')     || false;
var eveningDone = flow.get('evening_complete') || false;

if (avg <= START_SOC) {
    flow.set('gen_state', 1);
    flow.set('gen_start_time', Date.now());
    node.status({fill:'red', text:'LOW SOC ' + avg.toFixed(1) + '% - gen ON'});
    return [{payload:1, topic:'DO01'}, null];
}

if (avg >= STOP_SOC && gen === 1 && !eveningMode) {
    flow.set('gen_state', 0);
    flow.set('gen_start_time', null);
    node.status({fill:'green', text:'SOC OK ' + avg.toFixed(1) + '% - gen OFF'});
    return [{payload:0, topic:'DO01'}, null];
}

var now = new Date();
var h = now.getHours();
var m = now.getMinutes();
var inWindow = (h >= 18 || h < MORNING_HR);
var inGrace = (Date.now() - (flow.get('boot_time') || 0)) < 90000;
var afterSevenPm = (h >= 19 || h < MORNING_HR);
var socConfirmed = flow.get('soc_check_confirmed') || false;

if (inWindow && !eveningMode && !eveningDone && gen === 0 && !inGrace && (!afterSevenPm || socConfirmed)) {
    var avail = ((avg - RESERVE) / 100) * CAPACITY;
    if (avail < 0) avail = 0;

    var buf2 = flow.get('load_buffer') || [];
    var lkw;
    if (buf2.length >= BUFFER_SIZE) {
        var rec = buf2.slice(-BUFFER_SIZE);
        lkw = (rec.reduce(function(a,b){return a+b;},0) / rec.length) / 1000;
    } else {
        lkw = (h >= CUTOVER_HR || h < MORNING_HR) ? LOAD_LATE : LOAD_EARLY;
    }

    var hrs;
    if (h >= CUTOVER_HR) { hrs = (24 - h - (m/60)) + MORNING_HR; }
    else if (h < MORNING_HR) { hrs = MORNING_HR - h - (m/60); }
    else { hrs = 0; }

    var need = hrs * lkw;

    if (avail < need && kwhNow !== null && !isNaN(kwhNow)) {
        var deficit = need - avail;
        var target = kwhNow + deficit;
        flow.set('kwh_snapshot', kwhNow);
        flow.set('kwh_target', target);
        flow.set('evening_mode', true);
        flow.set('evening_fixed_stop', false);
        flow.set('gen_state', 1);
        flow.set('gen_start_time', Date.now());
        node.status({fill:'orange', text:'RECOVERY avg=' + avg.toFixed(1) + '% def=' + deficit.toFixed(0) + 'kWh tgt=' + target.toFixed(0)});
        return [{payload:1, topic:'DO01'}, {payload:'start_poll'}];
    }
}

if (afterSevenPm && !socConfirmed && !eveningMode && gen === 0) {
    node.status({fill:'grey', text:'avg=' + avg.toFixed(1) + '% - awaiting SOC check'});
} else {
    node.status({
        fill: gen ? 'red' : 'green',
        text: 'avg=' + avg.toFixed(1) + '% gen=' + (gen?'ON':'OFF') + (eveningMode?' [evening]':'') + (eveningDone?' [done]':'')
    });
}
return [null, null];

// Guards
if ((Date.now() - (flow.get('boot_time') || 0)) < 90000) {
    node.status({fill:'grey', text:'startup grace period'});
    return [null, {payload:{decision:'grace period'}}];
}
if (flow.get('gen_state') === 1) {
    node.status({fill:'grey', text:'gen already on'});
    return [null, {payload:{decision:'gen already on'}}];
}

var avg = flow.get('last_avg_soc');
if (avg === null || avg === undefined) {
    node.status({fill:'grey', text:'no SOC data'});
    return [null, {payload:{decision:'no SOC data'}}];
}

var now = new Date();
var h = now.getHours();
var m = now.getMinutes();
var mockH = flow.get('mock_hour');
if (mockH !== null && mockH !== undefined) h = parseInt(mockH);

var threshold = (h < 13) ? 35 : (h < 14) ? 40 : (h < 15) ? 50 : (h < 16) ? 60 : 90;

var CAPACITY      = 568;
var RESERVE       = 20;
var LOAD_LATE     = 25;
var LOAD_EARLY    = 35;
var CUTOVER_HR    = 21;
var MORNING_HR    = 5;
var OFFPEAK_FACTOR = 0.5;

var avail = ((avg - RESERVE) / 100) * CAPACITY;
if (avail < 0) avail = 0;

var peakCaptured = flow.get('peak_captured') || false;
var peakLkw = flow.get('peak_load_kw') || null;
var lkwEst = (peakCaptured && peakLkw) ? peakLkw * OFFPEAK_FACTOR : ((h >= CUTOVER_HR || h < MORNING_HR) ? LOAD_LATE : LOAD_EARLY);

var hrs;
if (h >= CUTOVER_HR)      { hrs = (24 - h - (m/60)) + MORNING_HR; }
else if (h < MORNING_HR)  { hrs = MORNING_HR - h - (m/60); }
else                      { hrs = (24 - h - (m/60)) + MORNING_HR; }

var need = hrs * lkwEst;
var surplus = avail - need;

var dbg = {
    soc:        parseFloat(avg.toFixed(1)),
    threshold:  threshold,
    avail_kwh:  parseFloat(avail.toFixed(0)),
    need_kwh:   parseFloat(need.toFixed(0)),
    surplus_kwh: parseFloat(surplus.toFixed(0)),
    model:      peakCaptured ? ('peak ' + (peakLkw||0).toFixed(1) + 'kW') : 'flat'
};

flow.set('soc_check_confirmed', true);

if (avg >= threshold) {
    node.status({fill:'green', text:'SOC ' + avg.toFixed(1) + '% >= ' + threshold + '% | avail=' + avail.toFixed(0) + ' need=' + need.toFixed(0) + 'kWh'});
    dbg.decision = 'SOC OK';
    return [null, {payload: dbg}];
}

if (surplus >= 0) {
    node.status({fill:'green', text:'SOC ' + avg.toFixed(1) + '% < ' + threshold + '% but surplus=' + surplus.toFixed(0) + 'kWh'});
    dbg.decision = 'battery sufficient';
    return [null, {payload: dbg}];
}

// Start generator
flow.set('gen_state', 1);
flow.set('evening_mode', true);
flow.set('evening_fixed_stop', false);
flow.set('evening_complete', false);
flow.set('start_soc', avg);
var kwhNow = flow.get('last_kwh') || 0;
flow.set('kwh_snapshot', kwhNow);
flow.set('gen_start_time', Date.now());

node.status({fill:'orange', text:'SOC ' + avg.toFixed(1) + '% deficit=' + (-surplus).toFixed(0) + 'kWh - gen ON'});
dbg.decision = 'gen START - deficit ' + (-surplus).toFixed(0) + 'kWh';
return [{payload: 1, topic: 'DO01'}, {payload: dbg}];

if (flow.get('peak_captured')) {
    node.status({fill:'green', text:'peak already captured'});
    return null;
}

var raw = msg.payload;
var loadW = null;

if (typeof raw === 'string') {
    loadW = parseFloat(raw.trim());
} else if (Array.isArray(raw)) {
    for (var i = 0; i < raw.length; i++) {
        var id = raw[i].nodeid || '';
        if (id === 'm13_ptot') {
            loadW = parseFloat(raw[i].value !== undefined ? raw[i].value : raw[i].payload);
        }
    }
} else if (raw && typeof raw === 'object') {
    loadW = parseFloat(raw['m13_ptot']);
}

if (loadW === null || isNaN(loadW) || loadW <= 0) {
    node.status({fill:'yellow', text:'bad read - skipping'});
    return null;
}

var buf = flow.get('peak_buffer') || [];
buf.push(loadW);
flow.set('peak_buffer', buf);

if (buf.length >= 15) {
    var avg = buf.reduce(function(a,b){return a+b;},0) / buf.length;
    var peakKw = avg / 1000;
    flow.set('peak_load_kw', peakKw);
    flow.set('peak_captured', true);
    flow.set('peak_buffer', []);
    node.status({fill:'blue', text:'peak captured ' + peakKw.toFixed(1) + 'kW (15 readings)'});
} else {
    node.status({fill:'yellow', text:'collecting ' + buf.length + '/15'});
}
return null;

var MAX_FAIL      = 3;
var BUFFER_SIZE   = 6;
var LOAD_LATE     = 25;
var LOAD_EARLY    = 35;
var OFFPEAK_FACTOR = 0.5;  // off-peak load as fraction of 7pm peak (tune this: 0.4=lower, 0.6=higher)
var CUTOVER_HR    = 21;
var MORNING_HR    = 5;

var eveningMode = flow.get('evening_mode') || false;
if (!eveningMode) { node.status({fill:'grey', text:'idle'}); return null; }

var now = new Date();
var h = now.getHours();
var m = now.getMinutes();

var raw = msg.payload;
var kwhNow = null;
var loadW = null;

if (typeof raw === 'string') {
    var parts = raw.split(',').map(function(v){return parseFloat(v.trim());});
    kwhNow = parts[0]; loadW = parts[1];
} else if (Array.isArray(raw)) {
    for (var i = 0; i < raw.length; i++) {
        var id = raw[i].nodeid || '';
        var val = parseFloat(raw[i].value !== undefined ? raw[i].value : raw[i].payload);
        if (id === 'm12_kwh_total') kwhNow = val;
        else if (id === 'm13_ptot') loadW = val;
    }
} else if (raw && typeof raw === 'object') {
    kwhNow = parseFloat(raw['m12_kwh_total']);
    loadW  = parseFloat(raw['m13_ptot']);
}

// Mock data fallback for bench testing (sensors not connected)
if (kwhNow === null || isNaN(kwhNow)) {
    var mk = flow.get('mock_kwh');
    if (mk !== null && mk !== undefined) kwhNow = parseFloat(mk);
}
if (loadW === null || isNaN(loadW)) {
    var ml = flow.get('mock_load');
    if (ml !== null && ml !== undefined) loadW = parseFloat(ml);
}

var failCount = context.get('fail_count') || 0;
if (kwhNow === null || isNaN(kwhNow)) {
    failCount++;
    context.set('fail_count', failCount);
    node.status({fill:'yellow', text:'bad read ' + failCount + '/' + MAX_FAIL});
    if (failCount < MAX_FAIL) return [null, {payload:'retry'}, null];
    return null;
}
context.set('fail_count', 0);

// Update rolling load buffer from m13
if (loadW !== null && !isNaN(loadW) && loadW > 0) {
    var buf = flow.get('load_buffer') || [];
    buf.push(loadW);
    if (buf.length > BUFFER_SIZE) buf = buf.slice(-BUFFER_SIZE);
    flow.set('load_buffer', buf);
}

// Rolling average load (m13)
var buf2 = flow.get('load_buffer') || [];
var lkw;
if (buf2.length >= BUFFER_SIZE) {
    lkw = (buf2.reduce(function(a,b){return a+b;},0) / buf2.length) / 1000;
} else {
    lkw = (h >= CUTOVER_HR || h < MORNING_HR) ? LOAD_LATE : LOAD_EARLY;
}

// Two-period need calculation
var peakCaptured = flow.get('peak_captured') || false;
var peakLkw      = flow.get('peak_load_kw')  || null;
var need;
var modelLabel;

if (peakCaptured && peakLkw) {
    var offpeakLkw = peakLkw * OFFPEAK_FACTOR;
    var peakHrs, offpeakHrs;
    if (h < CUTOVER_HR) {
        peakHrs    = CUTOVER_HR - h - (m/60);
        offpeakHrs = 8;
    } else {
        peakHrs    = 0;
        offpeakHrs = (h >= CUTOVER_HR) ? (24 - h - (m/60) + MORNING_HR) : (MORNING_HR - h - (m/60));
    }
    need = (peakHrs * peakLkw) + (offpeakHrs * offpeakLkw);
    modelLabel = '2p peak=' + peakLkw.toFixed(1) + 'kW off=' + offpeakLkw.toFixed(1) + 'kW';
} else {
    var hrs;
    if (h < MORNING_HR) { hrs = MORNING_HR - h - (m/60); }
    else                { hrs = (24 - h - (m/60)) + MORNING_HR; }
    need = hrs * lkw;
    modelLabel = 'flat ' + lkw.toFixed(1) + 'kW';
}

var avg = flow.get('last_avg_soc') || 0;
var avail = ((avg - 20) / 100) * 568;
if (avail < 0) avail = 0;

var startSoc = flow.get('start_soc') || 0;

// Stop early if battery has recovered +10%
if (startSoc > 0 && avg >= startSoc + 10) {
    flow.set('evening_mode', false);
    flow.set('evening_complete', false);
    flow.set('gen_state', 0);
    flow.set('gen_start_time', null);
    node.status({fill:'green', text:'SOC +10% recovery - gen OFF'});
    return [{payload:0, topic:'DO01'}, null, {payload:{
        decision:   'SOC +10% recovery stop',
        soc:        parseFloat(avg.toFixed(1)),
        start_soc:  parseFloat(startSoc.toFixed(1)),
        model:      modelLabel,
        avail_kwh:  parseFloat(avail.toFixed(0)),
        need_kwh:   parseFloat(need.toFixed(0))
    }}];
}

var deficit = need - avail;
if (deficit < 0) deficit = 0;
var snapshot = flow.get('kwh_snapshot') || kwhNow;
var target   = snapshot + deficit;
flow.set('kwh_target', target);

var progress = kwhNow - snapshot;

var dbg = {
    model:        modelLabel,
    load_kw:      parseFloat(lkw.toFixed(1)),
    soc:          parseFloat(avg.toFixed(1)),
    avail_kwh:    parseFloat(avail.toFixed(0)),
    need_kwh:     parseFloat(need.toFixed(0)),
    deficit_kwh:  parseFloat(deficit.toFixed(0)),
    progress_kwh: parseFloat(progress.toFixed(1)),
    target_kwh:   parseFloat(target.toFixed(0)),
    current_kwh:  parseFloat(kwhNow.toFixed(0))
};

node.status({fill:'blue', text:'[' + modelLabel + '] need=' + need.toFixed(0) + ' avail=' + avail.toFixed(0) + ' prog=' + progress.toFixed(0) + '/' + deficit.toFixed(0) + 'kWh'});

if (kwhNow >= target) {
    flow.set('evening_mode', false);
    flow.set('evening_complete', true);
    flow.set('gen_state', 0);
    flow.set('gen_start_time', null);
    node.status({fill:'green', text:'target reached ' + kwhNow.toFixed(0) + '/' + target.toFixed(0) + ' - gen OFF'});
    dbg.decision = 'target reached - gen OFF';
    return [{payload:0, topic:'DO01'}, null, {payload: dbg}];
}

dbg.decision = 'running';
return [null, {payload:'continue'}, {payload: dbg}];

flow.set('evening_complete', false);
flow.set('evening_fixed_stop', false);
flow.set('peak_captured', false);
flow.set('peak_load_kw', null);
flow.set('peak_buffer', []);
flow.set('soc_check_confirmed', false);
node.warn('Daily state reset at 2pm');
return null;

var raw = msg.payload;
if (typeof raw !== 'string') return null;
var parts = raw.split(',').map(function(v){return parseFloat(v.trim());});
if (parts.length < 4) return null;

var socs = parts.slice(0,4).filter(function(n){return !isNaN(n) && n > 0 && n <= 100;});
if (socs.length === 0) return null;

var avg = parseFloat((socs.reduce(function(a,b){return a+b;},0) / socs.length).toFixed(1));
var loadW = (parts.length >= 6 && !isNaN(parts[5])) ? parts[5] : null;
var loadKw = (loadW !== null) ? (loadW / 1000).toFixed(1) : '--';
var loadKwNum = (loadW !== null) ? parseFloat((loadW / 1000).toFixed(1)) : null;
var genState = flow.get('gen_state') || 0;

var lastKwh = (parts.length >= 5 && !isNaN(parts[4])) ? parts[4] : (flow.get('last_kwh') || 0);
var dailyStart = flow.get('daily_kwh_start');
if (dailyStart === null || dailyStart === undefined) {
    flow.set('daily_kwh_start', lastKwh);
    dailyStart = lastKwh;
}
var dailyKwh = Math.max(lastKwh - dailyStart, 0).toFixed(1);

var elapsedStr = '-';
var estRemStr = '-';
var peakStr = '--';
var soc1 = 0, soc2 = 0, soc3 = 0, soc4 = 0;
try {
    var genStartTime = flow.get('gen_start_time');
    if (genState && genStartTime) {
        var elapsedHrs = (Date.now() - genStartTime) / 3600000;
        var runH = Math.floor(elapsedHrs);
        var runM = Math.floor((elapsedHrs - runH) * 60);
        elapsedStr = runH + 'h ' + runM + 'm';
        var kwhSnap = flow.get('kwh_snapshot') || lastKwh;
        var kwhTgt = flow.get('kwh_target') || lastKwh;
        var produced = lastKwh - kwhSnap;
        var remaining = Math.max(kwhTgt - lastKwh, 0);
        var rate = elapsedHrs > 0.05 ? produced / elapsedHrs : 0;
        if (rate > 1 && remaining > 0) {
            var estHrs = remaining / rate;
            var estH = Math.floor(estHrs);
            var estM = Math.floor((estHrs - estH) * 60);
            estRemStr = '~' + estH + 'h ' + estM + 'm';
        } else if (remaining === 0) {
            estRemStr = 'Target met';
        }
    }
    var peakKw = flow.get('peak_load_kw');
    peakStr = peakKw ? peakKw.toFixed(1) + ' kW' : '--';
    soc1 = (!isNaN(parts[0]) && parts[0] > 0) ? Math.round(parts[0]) : 0;
    soc2 = (!isNaN(parts[1]) && parts[1] > 0) ? Math.round(parts[1]) : 0;
    soc3 = (!isNaN(parts[2]) && parts[2] > 0) ? Math.round(parts[2]) : 0;
    soc4 = (!isNaN(parts[3]) && parts[3] > 0) ? Math.round(parts[3]) : 0;
} catch(e) { node.warn('fmt_dashboard extra: ' + e.message); }

return [
    {payload: avg},
    {payload: loadKw + ' kW'},
    {payload: {state: genState ? 'RUNNING' : 'STANDBY', load_kw: loadKw, elapsed: elapsedStr, daily_kwh: dailyKwh, est_remaining: estRemStr, peak_kw: peakStr}},
    loadKwNum !== null ? {payload: loadKwNum, topic: 'Site Load (kW)'} : null,
    {payload: {soc1: soc1, soc2: soc2, soc3: soc3, soc4: soc4}}
];

var lastKwh = flow.get('last_kwh') || 0;
flow.set('daily_kwh_start', lastKwh);
node.status({fill:'blue', text:'midnight: daily start=' + lastKwh.toFixed(1) + ' kWh'});
return null;
